<?php

declare(strict_types=1);

namespace Database\Seeders\Japanese;

use Database\Seeders\Concerns\SeedsLearningContent;
use Illuminate\Database\Seeder;

/**
 * Japanese reading practice (読解) — 20 Indonesian folk tales retold in
 * Japanese, at JLPT levels N5-N3. 17 of them are also retold in English by
 * LearningContentSeeder::readingStories(), so learners get the same story in
 * both languages; `translated_content` is an independent Indonesian retelling
 * for each entry rather than a shared string between the two languages.
 */
class ReadingSeeder extends Seeder
{
    use SeedsLearningContent;

    public function run(): void
    {
        $stories = $this->stories();
        $count = $this->fill('membaca-jepang', $stories);

        $this->command?->info('  membaca: '.$count.' kosakata glosarium ('.count($stories).' cerita)');
    }

    /** @param array<int, array<string, mixed>> $rows */
    private function glossary(array $rows): array
    {
        return array_map(fn (array $r) => [
            'term' => $r[0],
            'reading' => $r[1],
            'romaji' => $r[2],
            'meaning' => $r[3],
            'extra' => ['type' => 'glossary'],
        ], $rows);
    }

